"""Compare every schema generated by the same frozen official/patched native CLI."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import tarfile
import uuid

from assemble_release_acceptance import qualification_scope,require,sha,load


def compare_schemas(official,patched,expected_count):
    def inventory(root):
        result={}
        for path in root.rglob('*.json'):
            require(path.is_file() and not path.is_symlink(),'Schema export contains a non-regular JSON file')
            value=json.loads(path.read_text(encoding='utf-8'))
            result[path.relative_to(root).as_posix()]=hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':')).encode()).hexdigest()
        return result
    left=inventory(official);right=inventory(patched)
    differences=sorted(name for name in left.keys()|right.keys() if left.get(name)!=right.get(name))
    return {'passed':len(left)==len(right)==expected_count and not differences,
            'schemas_compared':len(left.keys()&right.keys()),'official_schema_count':len(left),'patched_schema_count':len(right),
            'expected_schema_count':expected_count,'differences':differences,'schema_sha256':{'official':left,'patched':right}}


def main():
    p=argparse.ArgumentParser()
    for name in ['official','patched','native-manifest','official-archive','output']:p.add_argument('--'+name,type=Path,required=True)
    p.add_argument('--official-archive-sha256',required=True);p.add_argument('--official-target',required=True);args=p.parse_args()
    native=load(args.native_manifest);scope=qualification_scope(native)
    official=args.official.resolve();patched=args.patched.resolve();archive=args.official_archive.resolve()
    require(sha(archive)==args.official_archive_sha256,'Official release archive checksum differs from its pinned upstream asset')
    official_hash=sha(official);patched_hash=sha(patched)
    require(patched_hash==native['files']['bin/codex'+('.exe' if scope['target']=='x86_64-pc-windows-msvc' else '')],
            'Patched binary differs from the selected native manifest')
    members=[]
    with tarfile.open(archive) as bundle:
        for member in bundle.getmembers():
            if member.isfile():
                with bundle.extractfile(member) as stream:digest=hashlib.file_digest(stream,'sha256').hexdigest()
                if digest==official_hash:members.append(member.name)
    require(len(members)==1,'Official CLI is not exactly one binary in the pinned release archive')
    root=args.output.resolve()/str(uuid.uuid4());root.mkdir(parents=True,mode=0o700)
    verifier_hash=sha(__file__);commands=[]
    for name,binary in [('official',official),('patched',patched)]:
        home=root/(name+'-home');home.mkdir();output=root/name
        env={key:value for key,value in os.environ.items() if not key.startswith('CODEX_') and key not in {'OPENROUTER_API_KEY','OPENAI_API_KEY'}}
        env['CODEX_HOME']=str(home)
        version=subprocess.run([str(binary),'--version'],env=env,capture_output=True,text=True,encoding='utf-8',timeout=30)
        require(version.returncode==0 and version.stdout.strip()=='codex-cli '+native['upstream_version'],'Native CLI version differs from the frozen upstream version')
        argv=[str(binary),'app-server','generate-json-schema','--experimental','--out',str(output)]
        result=subprocess.run(argv,env=env,capture_output=True,text=True,encoding='utf-8',timeout=120)
        (root/(name+'.log')).write_text(result.stdout+result.stderr,encoding='utf-8')
        commands.append({'name':name,'argv':argv,'version':version.stdout.strip(),'exit':result.returncode})
        require(result.returncode==0,'Native schema export failed: '+name)
    report=compare_schemas(root/'official',root/'patched',scope['native_schema_count'])
    report.update(target=scope['target'],official_target=args.official_target,upstream_commit=native['upstream_commit'],
                  upstream_version=native['upstream_version'],official_binary_sha256=official_hash,patched_binary_sha256=patched_hash,
                  official_archive_sha256=sha(archive),official_archive_member=members[0],native_manifest=native,commands=commands,
                  verifier_sha256={'verify_native_schema.py':verifier_hash},
                  scope='Complete experimental app-server schemas; official musl and patched GNU Linux may differ in libc linkage but use the same frozen upstream release.')
    report['binary_and_verifier_unchanged']=sha(official)==official_hash and sha(patched)==patched_hash and sha(__file__)==verifier_hash
    report['passed']=report['passed'] and report['binary_and_verifier_unchanged']
    (root/'verdict.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({key:report[key] for key in ['passed','schemas_compared','differences','target','official_target']}),flush=True)
    print('EVIDENCE',root,flush=True)
    require(report['passed'],'Native schema comparison failed')


if __name__=='__main__':main()
